def norm(cells): 
    ys=[y for y,_ in cells]; xs=[x for _,x in cells]; mh=max(ys)-min(ys)+1; mw=max(xs)-min(xs)+1
    m=[[0]*mw for _ in range(mh)]
    for y,x in cells: m[y-min(ys)][x-min(xs)]=1
    return tuple(tuple(row) for row in m), min(ys), min(xs)
