def solve(g,bg=0,policy='downfirst',order='bottom'):
    H=len(g); W=len(g[0]); cs=comps4(g)
    if order=='bottom': cs.sort(key=lambda z:-max(y for y,x in z[1]))
    else: cs.sort(key=lambda z:min(y for y,x in z[1]))
    occ=set(); out=[[bg]*W for _ in range(H)]
    def blocked(cells,dx,dy):
        n={(y+dy,x+dx) for y,x in cells}
        return any(not(0<=y<H and 0<=x<W) or (y,x) in occ for y,x in n)
    for c,cells in cs:
        cur=set(cells)
        # slide down
        if policy in ('downfirst','both'):
            while not blocked(cur,1,0): cur={(y+1,x) for y,x in cur}
        # slide left
        while not blocked(cur,0,-1): cur={(y,x-1) for y,x in cur}
        for y,x in cur: out[y][x]=c
        occ|=cur
    return out
